<script module lang="ts">
/**
 * A colour field: a swatch, a hex entry and a picker popover (`design/components/color-input.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/color-input.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy, setContext } from 'svelte'

import * as zag from '@zag-js/color-picker'
import { useMachine } from '@zag-js/svelte'

import {
  COLOR_INPUT_REST,
  agentMember,
  attributes,
  composingKey,
  joinSlot,
  mergeParts,
  normalizeProps,
  useDirection,
  watchEffect,
} from '@polymorph/svelte'
import styles from '@polymorph/recipes/controls/color-input.module.css'
import a11y from '@polymorph/recipes/conventions/a11y.module.css'
import Input from './Input.svelte'
import Popover from '../overlays/Popover.svelte'

export interface ColorInputProps {
  /**
   * Enables the alpha channel: the alpha rail, the eight-digit hex and the checker.
   */
  alpha?: boolean
  'aria-describedby'?: string
  /**
   * Set by FormField. Set it directly only when there is no visible label.
   */
  'aria-label'?: string
  'aria-labelledby'?: string
  'aria-required'?: boolean
  /**
   * Opens the picker on mount, for galleries and tests. Screens let the user open it.
   */
  defaultOpen?: boolean
  defaultValue?: string
  disabled?: boolean
  id?: string
  invalid?: boolean
  /**
   * Serializes the hex through a hidden input.
   */
  name?: string
  /**
   * Fires continuously while dragging, as Input does, with no separate commit as on Slider.
   */
  onChange?: (value: string) => void
  /**
   * Names the swatch button and the popover, for example "Choose accent colour".
   */
  pickerLabel: string
  size?: 'sm' | 'md' | 'lg'
  /**
   * Lowercase hex: `#rrggbb`, or `#rrggbbaa` with `alpha`.
   */
  value?: string
}
</script>

<script lang="ts">
let {
  alpha = false,
  'aria-describedby': ariaDescribedbyOwn,
  'aria-label': ariaLabel,
  'aria-labelledby': ariaLabelledbyOwn,
  'aria-required': ariaRequiredOwn,
  defaultOpen,
  defaultValue,
  disabled = false,
  id: idOwn,
  invalid: invalidOwn = false,
  name,
  onChange,
  pickerLabel,
  size = 'md',
  value,
}: ColorInputProps = $props()
const uid = $props.id()
const joined = joinSlot(undefined, () => ({ disabled: disabled, name: name, size: size }))
const ariaDescribedby = $derived(
  joined.passed['aria-describedby'] === undefined
    ? ariaDescribedbyOwn
    : (joined.passed['aria-describedby'] as typeof ariaDescribedbyOwn),
)
const ariaLabelledby = $derived(
  joined.passed['aria-labelledby'] === undefined
    ? ariaLabelledbyOwn
    : (joined.passed['aria-labelledby'] as typeof ariaLabelledbyOwn),
)
const ariaRequired = $derived(
  joined.passed['aria-required'] === undefined
    ? ariaRequiredOwn
    : (joined.passed['aria-required'] as typeof ariaRequiredOwn),
)
const id = $derived(
  joined.passed['id'] === undefined ? idOwn : (joined.passed['id'] as typeof idOwn),
)
const invalid = $derived(
  joined.passed['invalid'] === undefined
    ? invalidOwn
    : (joined.passed['invalid'] as typeof invalidOwn),
)
setContext('polymorph:identity', 'color-input')
const borrowed: { element?: () => Element | null | undefined } = {}
setContext('polymorph:borrowed', borrowed)
let mirror = $state(null as string | null)
let draft = $state(null as string | null)
let hexField = $state<HTMLElement | null>(null)
let root = $state<HTMLElement | null>(null)
const parseHex = $derived((text: string) =>
  ((bare: string) =>
    /^([0-9a-f]{3}|[0-9a-f]{6}|[0-9a-f]{8})$/i.test(bare)
      ? ((parsed) => (alpha ? parsed : parsed.withChannelValue('alpha', 1)))(
          zag.parse(`#${bare}`).toFormat('hsba'),
        )
      : null)(text.trim().replace(/^#/, '')),
)
const formatHex = $derived((shown: { toString: (format: 'hex' | 'hexa') => string }) =>
  shown.toString(alpha ? 'hexa' : 'hex').toLowerCase(),
)
const kept = $derived(
  mirror === null
    ? (parseHex(defaultValue ?? COLOR_INPUT_REST) ?? parseHex(COLOR_INPUT_REST))!
    : zag.parse(mirror),
)
const controlled = $derived(value === undefined ? null : parseHex(value))
const color = $derived(
  controlled !== null && formatHex(controlled) !== formatHex(kept) ? controlled : kept,
)
const hex = $derived(formatHex(color))
const setColor = $derived(
  (next: {
    toFormat: (format: 'hsba') => { toString: (format: 'hsba' | 'hex' | 'hexa') => string }
  }) =>
    ((normalized) => ((mirror = normalized.toString('hsba')), onChange?.(formatHex(normalized))))(
      next.toFormat('hsba'),
    ),
)
const commitDraft = $derived(
  () =>
    draft !== null &&
    ((next) => ((draft = null), next !== null && setColor(next)))(parseHex(draft)),
)
const toDraft = $derived((text: string) =>
  text
    .replace(/#/g, '')
    .trim()
    .slice(0, alpha ? 8 : 6),
)
const documentDirection = useDirection(() => root)
const service = useMachine(
  zag.machine,
  () =>
    ({
      id: uid,
      dir: documentDirection.current,
      value: color,
      format: 'hsba' as const,
      inline: true,
      disabled: disabled,
      onValueChange: (details) => {
        setColor(details.value)
      },
    }) as Partial<zag.Props>,
)
const api = $derived(zag.connect(service, normalizeProps))
const held = $derived(api.dragging ? service.context.get('activeId') : null)
const fills = $derived({
  hue: (api.getChannelSliderTrackProps({ channel: 'hue' }).style as { backgroundImage?: string })
    .backgroundImage,
  alpha: (
    api.getChannelSliderTrackProps({ channel: 'alpha' }).style as { backgroundImage?: string }
  ).backgroundImage,
})
const fromRange = $derived((channel: 'saturation' | 'brightness' | 'hue' | 'alpha', event: Event) =>
  api.setChannelValue(channel, Number((event.target as HTMLInputElement).value)),
)
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'ColorInput',
    element: () => hexField?.querySelector('input'),
    state: () => ({ value: hex, disabled: disabled, invalid: invalid }),
    actions: {
      set: {
        argument: 'text',
        run: (value) =>
          (() => {
            const next = parseHex(value)
            if (next === null) throw new Error(`"${value}" is not a hex colour.`)
            draft = null
            setColor(next)
          })(),
      },
    },
    withholds: () => [root, borrowed.element?.()],
  })
  release1 = () => {
    ran()
  }
}
watchEffect(effect1)
onDestroy(() => release1?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<span
    bind:this={root}
    class={styles.root}
    data-size={size}
    data-disabled={(disabled) ? '' : undefined}
    data-invalid={(invalid) ? '' : undefined}
    data-alpha={(alpha) ? '' : undefined}
    data-member="color-input"
    >{#snippet triggerOfPopover1()
      }<button class={styles.swatch} type="button" {disabled} aria-label={pickerLabel}
        ><span class={styles.swatchFill} style:--pm-color-input-swatch={color.toString('css')}></span
      ></button
    >{/snippet
    }<Popover label={pickerLabel} {defaultOpen} align="start" trigger={triggerOfPopover1}
      ><div class={styles.picker}
        ><div
          {...attributes(mergeParts(api.getAreaBackgroundProps(), api.getAreaProps()))}
          class={styles.plane}
          ><span
            {...attributes(api.getAreaThumbProps())}
            class={styles.thumb}
            tabindex={(undefined) as never}
            role={undefined}
            aria-label={undefined}
            aria-valuenow={undefined}
            aria-valuemin={undefined}
            aria-valuemax={undefined}
            aria-valuetext={undefined}
            aria-roledescription={undefined}
            aria-orientation={undefined}
            aria-disabled={undefined}
            data-state={held === 'area' ? 'dragging' : undefined}
            ><input
              class={a11y.visuallyHidden}
              type="range"
              min={color.getChannelRange('saturation').minValue}
              max={color.getChannelRange('saturation').maxValue}
              step={color.getChannelRange('saturation').step}
              value={color.getChannelValue('saturation')}
              {disabled}
              aria-label={api.getAreaThumbProps()['aria-label']}
              aria-valuetext={api.getAreaThumbProps()['aria-valuetext']}
              oninput={(event) => { fromRange('saturation', event) }}
            /><input
              class={a11y.visuallyHidden}
              type="range"
              min={color.getChannelRange('brightness').minValue}
              max={color.getChannelRange('brightness').maxValue}
              step={color.getChannelRange('brightness').step}
              value={color.getChannelValue('brightness')}
              {disabled}
              tabindex="-1"
              aria-hidden="true"
              oninput={(event) => { fromRange('brightness', event) }}
          /></span
        ></div
        ><div
          {...attributes(api.getChannelSliderProps({ channel: 'hue' }))}
          class={styles.rail}
          data-checker={undefined}
          ><span class={styles.railFill} style:background-image={fills.hue} aria-hidden="true"></span
          ><span
            {...attributes(api.getChannelSliderThumbProps({ channel: 'hue' }))}
            class={styles.thumb}
            tabindex={(undefined) as never}
            role={undefined}
            aria-label={undefined}
            aria-valuenow={undefined}
            aria-valuemin={undefined}
            aria-valuemax={undefined}
            aria-valuetext={undefined}
            aria-roledescription={undefined}
            aria-orientation={undefined}
            aria-disabled={undefined}
            data-state={held === 'hue' ? 'dragging' : undefined}
            ><input
              class={a11y.visuallyHidden}
              type="range"
              min={color.getChannelRange('hue').minValue}
              max={color.getChannelRange('hue').maxValue}
              step={color.getChannelRange('hue').step}
              value={color.getChannelValue('hue')}
              {disabled}
              aria-label={api.getChannelSliderThumbProps({ channel: 'hue' })['aria-label']}
              aria-valuetext={api.getChannelSliderThumbProps({ channel: 'hue' })['aria-valuetext']}
              oninput={(event) => { fromRange('hue', event) }}
          /></span
        ></div
        >{#if alpha
          }<div
            {...attributes(api.getChannelSliderProps({ channel: 'alpha' }))}
            class={styles.rail}
            data-checker=""
            ><span class={styles.railFill} style:background-image={fills.alpha} aria-hidden="true"></span
            ><span
              {...attributes(api.getChannelSliderThumbProps({ channel: 'alpha' }))}
              class={styles.thumb}
              tabindex={(undefined) as never}
              role={undefined}
              aria-label={undefined}
              aria-valuenow={undefined}
              aria-valuemin={undefined}
              aria-valuemax={undefined}
              aria-valuetext={undefined}
              aria-roledescription={undefined}
              aria-orientation={undefined}
              aria-disabled={undefined}
              data-state={held === 'alpha' ? 'dragging' : undefined}
              ><input
                class={a11y.visuallyHidden}
                type="range"
                min={color.getChannelRange('alpha').minValue}
                max={color.getChannelRange('alpha').maxValue}
                step={color.getChannelRange('alpha').step}
                value={color.getChannelValue('alpha')}
                {disabled}
                aria-label={api.getChannelSliderThumbProps({ channel: 'alpha' })['aria-label']}
                aria-valuetext={api.getChannelSliderThumbProps({ channel: 'alpha' })['aria-valuetext']}
                oninput={(event) => { fromRange('alpha', event) }}
            /></span
          ></div
        >{/if
      }</div
    ></Popover
    ><span
      bind:this={hexField}
      class={styles.field}
      onkeydown={(event) => { if (event.key === 'Enter' && !composingKey(event)) commitDraft() }}
      ><Input
        value={draft ?? hex.replace(/^#/, '')}
        prefix="#"
        {size}
        {disabled}
        {invalid}
        {id}
        autoComplete="off"
        aria-label={ariaLabel}
        aria-labelledby={ariaLabelledby}
        aria-describedby={ariaDescribedby}
        aria-required={ariaRequired}
        onChange={(event) => { draft = toDraft(event) }}
        onBlur={() => { commitDraft() }}
    /></span
    >{#if name !== undefined}<input type="hidden" {name} value={hex} />{/if
  }</span
>{/if
}{@render joined.end?.()}
